use std::ops::{Deref, DerefMut};
pub struct HeaderName(String);
impl HeaderName {
    pub fn new(value: String) -> Option<Self> {
        if !value.is_empty() && value.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-') {
            Some(Self(value))
        } else { None }
    }
}
impl Deref for HeaderName {
    type Target = String;
    fn deref(&self) -> &String { &self.0 }
}
impl DerefMut for HeaderName {
    fn deref_mut(&mut self) -> &mut String { &mut self.0 }
}
pub fn wire_header(name: &HeaderName) -> String { format!("{}: value\r\n", name.as_str()) }

