pub async fn sum_three(values: [u8; 3]) -> Result<u16, tokio::task::JoinError> {
    let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel();
    let worker = tokio::spawn(async move {
        for value in values {
            if tx.send(value).is_err() { return; }
        }
    });
    let mut total = 0u16;
    while let Some(value) = rx.recv().await { total += u16::from(value); }
    worker.await?;
    Ok(total)
}

